219	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
220	    @Override
221	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
222	        Owner owner = this.clinicService.findOwnerById(ownerId);
223	        if (owner != null) {
224	            Pet pet = owner.getPet(petId);
225	            if (pet != null) {
226	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
227	            }
228	        }
229	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
230	    }
231	
232	    /**
233	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
234	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
235	     * the request body already rejects null and empty values, but permits whitespace-only strings
236	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
237	     * that gap so every required field must carry a non-blank value.
238	     *
239	     * @param ownerFieldsDto the submitted owner fields
240	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
241	     */
242	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
243	        List<String> missing = new ArrayList<>();
244	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
245	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
246	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
247	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
248	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
249	        if (!missing.isEmpty()) {
250	            throw new InvalidOwnerFieldsException(missing);
251	        }
252	    }
253	
254	    private void addIfBlank(List<String> missing, String fieldName, String value) {
255	        if (value == null || value.isBlank()) {
256	            missing.add(fieldName);
257	        }
258	    }
259	
260	    /**
261	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
262	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
263	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
264	     * {@code 400 Bad Request}.
265	     *
266	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
267	     *                       {@link #rejectBlankOwnerFields} having already run)
268	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
269	     */
270	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
271	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
272	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
273	        ownerFieldsDto.setTelephone(normalized);
274	    }
275	
276	    /**
277	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
278	     * untouched (email is optional). When present it is trimmed and, after validating that it is a
279	     * syntactically valid address, written back lower-cased so it is the value stored and returned.
280	     * Any present-but-invalid address is rejected with a {@code 400 Bad Request}.
281	     *
282	     * @param ownerFieldsDto the submitted owner fields
283	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address
284	     */
285	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
286	        String email = ownerFieldsDto.getEmail();
287	        if (email == null || email.isBlank()) {
288	            return;
289	        }
290	        email = email.trim();
291	        if (!EMAIL_PATTERN.matcher(email).matches()) {
292	            throw new InvalidOwnerFieldsException(List.of("email"));
293	        }
294	        ownerFieldsDto.setEmail(email.toLowerCase(Locale.ROOT));
295	    }
296	
297	    /**
298	     * Rejects creating an owner whose normalized telephone is already used by any other owner.
299	     * Both the submitted telephone and every existing owner's stored telephone are reduced to their
300	     * {@linkplain TelephoneNormalizer#toComparisonKey comparison key} before comparison, so equality
301	     * is judged on that key alone. A match is reported as a {@code 409 Conflict}.
302	     *
303	     * @param normalizedTelephone the submitted telephone, already reduced to its canonical form by
304	     *                            {@link #normalizeTelephone}
305	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same telephone
306	     */
307	    private void rejectDuplicateTelephone(String normalizedTelephone) {
308	        String comparisonKey = TelephoneNormalizer.toComparisonKey(normalizedTelephone);
309	        boolean inUse = this.clinicService.findAllOwners().stream()
310	            .map(Owner::getTelephone)
311	            .filter(Objects::nonNull)
312	            .map(TelephoneNormalizer::toComparisonKey)
313	            .anyMatch(comparisonKey::equals);
314	        if (inUse) {
315	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
316	        }
317	    }
318	
319	    /**
320	     * Rejects creating an owner who shares a household with any existing owner, unless the request
321	     * opts in with {@code sharesHousehold} set to {@code true}. Two owners share a household when they
322	     * have the same {@code lastName} and {@code address}, compared case-insensitively and with runs of
323	     * whitespace collapsed (see {@link HouseholdNormalizer}); the submitted fields and every existing
324	     * owner's stored fields are reduced to their {@linkplain HouseholdNormalizer#toComparisonKey
325	     * comparison key} before comparison. A match is reported as a {@code 409 Conflict}.
326	     *
327	     * @param ownerFieldsDto the submitted owner fields (its {@code lastName} and {@code address} are
328	     *                       non-blank here, {@link #rejectBlankOwnerFields} having already run)
329	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household and the
330	     *                                          request did not opt in with {@code sharesHousehold}
331	     */
332	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
333	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
334	            return;
335	        }
336	        String comparisonKey = HouseholdNormalizer.toComparisonKey(
337	            ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
338	        boolean inUse = this.clinicService.findAllOwners().stream()
339	            .filter(owner -> owner.getLastName() != null && owner.getAddress() != null)
340	            .map(owner -> HouseholdNormalizer.toComparisonKey(owner.getLastName(), owner.getAddress()))
341	            .anyMatch(comparisonKey::equals);
342	        if (inUse) {
343	            throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
344	        }
345	    }
346	}
